#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <sys/resource.h>

int getrusage(__rusage_who_t who, struct rusage *usage) {
    static unsigned calls;
    const char *mode = getenv("WIRL_FAULT_TEST");
    calls++;
    memset(usage, 0, sizeof(*usage));
    if (mode && ((strcmp(mode, "before-error") == 0 && calls == 1)
                 || (strcmp(mode, "after-error") == 0 && calls == 2))) {
        errno = EIO;
        return -1;
    }
    if (mode && strcmp(mode, "fault") == 0 && calls == 2) usage->ru_majflt = 1;
    return 0;
}
